section.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/django-services.json",
  "type": "object",
  "title": "Django Services Layer",
  "required": [
    "service_name",
    "module_path",
    "aggregate",
    "kw_only",
    "type_hints_complete",
    "write_count",
    "atomic",
    "side_effects_on_commit",
    "http_imports",
    "orm_outside_services",
    "tests_path"
  ],
  "additionalProperties": false,
  "properties": {
    "service_name": {
      "type": "string",
      "minLength": 1,
      "description": "entity_action name."
    },
    "module_path": {
      "type": "string",
      "minLength": 1,
      "pattern": "^[a-z_][a-z0-9_]*(\\.[a-z_][a-z0-9_]*)*\\.services(\\.[a-z_][a-z0-9_]*)?$",
      "description": "Dotted path apps.<app>.services (file form app/services/<aggregate>.py maps onto it)."
    },
    "aggregate": {
      "type": "string",
      "minLength": 2,
      "description": "Aggregate the module owns; one module per aggregate, never per caller type."
    },
    "public_functions": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "minItems": 1,
      "description": "Public service functions exported by the module."
    },
    "kw_only": {
      "type": "boolean",
      "description": "All args keyword-only."
    },
    "type_hints_complete": {
      "type": "boolean",
      "description": "Return + arg types declared."
    },
    "write_count": {
      "type": "integer",
      "minimum": 0,
      "description": "Number of writes performed."
    },
    "atomic": {
      "type": "boolean",
      "description": "Wrapped in @transaction.atomic."
    },
    "side_effects_on_commit": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Side effects dispatched via on_commit."
    },
    "http_imports": {
      "type": "integer",
      "minimum": 0,
      "maximum": 0,
      "description": "Imports of django.http / rest_framework.response / template engines inside the service module; must be 0."
    },
    "orm_outside_services": {
      "type": "integer",
      "minimum": 0,
      "maximum": 0,
      "description": "ORM mutations found outside services/ for this aggregate; must be 0."
    },
    "validated_at": {
      "type": "string",
      "format": "date-time",
      "description": "When the artefact last passed the validator."
    },
    "tests_path": {
      "type": "string",
      "minLength": 1,
      "description": "Path to the service tests."
    }
  }
}
